std::optional<Vec3> Refract(
    const Vec3& incident,
    const Vec3& normal,
    float etaIncident,
    float etaTransmitted)
{
    // incident points toward the interface.
    // normal points into the incident medium.

    const float eta =
        etaIncident / etaTransmitted;

    const float cosIncident =
        std::clamp(
            -Dot(normal, incident),
            0.0f,
            1.0f);

    // Snell:
    // sin²(theta_t)
    const float sin2Transmitted =
        eta * eta *
        (1.0f -
         cosIncident * cosIncident);

    // No real transmitted angle exists.
    if (sin2Transmitted > 1.0f)
        return std::nullopt;

    const float cosTransmitted =
        std::sqrt(
            1.0f -
            sin2Transmitted);

    return Normalize(
        eta * incident +
        (
            eta * cosIncident -
            cosTransmitted
        ) * normal);
}

const float PI = 3.14159265359;

float GGXDistribution(
    float NdotH,
    float perceptualRoughness)
{
    // Artist-facing roughness is mapped to microfacet alpha.
    float alpha =
        perceptualRoughness *
        perceptualRoughness;

    float alpha2 =
        alpha * alpha;

    float d =
        NdotH * NdotH *
        (alpha2 - 1.0) +
        1.0;

    return
        alpha2 /
        max(
            PI * d * d,
            1e-7);
}

float SchlickGGXGeometry1(
    float NdotX,
    float perceptualRoughness)
{
    // Common direct-light approximation to Smith GGX.
    float r =
        perceptualRoughness +
        1.0;

    float k =
        (r * r) / 8.0;

    return
        NdotX /
        max(
            NdotX * (1.0 - k) + k,
            1e-7);
}

float SmithGeometry(
    float NdotL,
    float NdotV,
    float perceptualRoughness)
{
    return
        SchlickGGXGeometry1(
            NdotL,
            perceptualRoughness)
        *
        SchlickGGXGeometry1(
            NdotV,
            perceptualRoughness);
}

vec3 FresnelSchlick(
    float VdotH,
    vec3 F0)
{
    float x =
        1.0 -
        clamp(VdotH, 0.0, 1.0);

    float x5 =
        x * x * x * x * x;

    return
        F0 +
        (vec3(1.0) - F0) *
        x5;
}

vec3 EvaluateMetallicRoughnessBRDF(
    vec3 N,
    vec3 V,
    vec3 L,
    vec3 baseColor,
    float metallic,
    float roughness)
{
    float NdotL =
        max(dot(N, L), 0.0);

    float NdotV =
        max(dot(N, V), 0.0);

    if (NdotL <= 0.0 ||
        NdotV <= 0.0)
    {
        return vec3(0.0);
    }

    vec3 H =
        normalize(L + V);

    float NdotH =
        max(dot(N, H), 0.0);

    float VdotH =
        max(dot(V, H), 0.0);

    // Dielectric interface ≈ 4% at normal incidence.
    // Metallic workflow replaces this by colored conductor reflectance.
    vec3 F0 =
        mix(
            vec3(0.04),
            baseColor,
            metallic);

    float D =
        GGXDistribution(
            NdotH,
            roughness);

    float G =
        SmithGeometry(
            NdotL,
            NdotV,
            roughness);

    vec3 F =
        FresnelSchlick(
            VdotH,
            F0);

    vec3 specular =
        D * G * F /
        max(
            4.0 *
            NdotL *
            NdotV,
            1e-6);

    // Energy not immediately reflected at the interface can contribute
    // to dielectric body/diffuse scattering.
    vec3 diffuseWeight =
        (vec3(1.0) - F) *
        (1.0 - metallic);

    vec3 diffuse =
        diffuseWeight *
        baseColor /
        PI;

    // This function returns the BRDF itself.
    // The caller still multiplies by incident radiance and NdotL.
    return
        diffuse +
        specular;
}

Color TraceWhitted(
    Scene scene,
    Ray ray,
    uint32_t depth)
{
    if (depth > MaxDepth)
        return black;

    hit = scene.Intersect(ray);

    if (!hit)
        return environment;

    if (emissive)
        return emission;

    if (mirror)
        return Trace(reflectionRay);

    if (glass)
        return
            F * Trace(reflectionRay)
            +
            (1-F) * Trace(refractionRay);

    return DirectLighting(hit);
}

struct Ray
{
    Vec3 Origin;
    Vec3 Direction;

    float TMin = 0.0f;
    float TMax =
        std::numeric_limits<float>::infinity();

    [[nodiscard]]
    Vec3 At(float t) const noexcept
    {
        return Origin +
               Direction * t;
    }

    [[nodiscard]]
    bool Contains(float t) const noexcept
    {
        return
            t >= TMin &&
            t <= TMax;
    }
};

