std::optional<Hit>
TraceClosest(
    const Ray& inputRay,
    const BVH& bvh)
{
    if (bvh.nodes.empty())
        return std::nullopt;

    Ray ray = inputRay;

    std::optional<Hit> closest;

    // Local stack avoids recursive function-call overhead.
    std::array<uint32_t, 64> stack{};
    uint32_t stackSize = 0;

    stack[stackSize++] = 0; // root

    while (stackSize > 0)
    {
        const uint32_t nodeIndex =
            stack[--stackSize];

        const BVHNode& node =
            bvh.nodes[nodeIndex];

        float nodeNear = 0.0f;

        if (!IntersectAABB(
                ray,
                node.bounds,
                nodeNear))
        {
            continue;
        }

        // Since ray.tMax shrinks whenever a closer primitive is found,
        // far nodes naturally become rejectable.
        if (nodeNear > ray.tMax)
            continue;

        if (node.IsLeaf())
        {
            for (uint32_t i = 0;
                 i < node.primitiveCount;
                 ++i)
            {
                const uint32_t primitiveIndex =
                    bvh.primitiveIndices[
                        node.firstPrimitive + i];

                auto hit =
                    IntersectPrimitive(
                        ray,
                        primitiveIndex);

                if (hit &&
                    hit->t < ray.tMax)
                {
                    closest = hit;

                    // Tighten the query.
                    ray.tMax = hit->t;
                }
            }

            continue;
        }

        float leftNear;
        float rightNear;

        const bool hitLeft =
            IntersectAABB(
                ray,
                bvh.nodes[node.left].bounds,
                leftNear);

        const bool hitRight =
            IntersectAABB(
                ray,
                bvh.nodes[node.right].bounds,
                rightNear);

        // Push farther child first because stack is LIFO.
        // The nearer child is processed immediately.
        if (hitLeft && hitRight)
        {
            if (leftNear < rightNear)
            {
                stack[stackSize++] =
                    node.right;

                stack[stackSize++] =
                    node.left;
            }
            else
            {
                stack[stackSize++] =
                    node.left;

                stack[stackSize++] =
                    node.right;
            }
        }
        else if (hitLeft)
        {
            stack[stackSize++] =
                node.left;
        }
        else if (hitRight)
        {
            stack[stackSize++] =
                node.right;
        }
    }

    return closest;
}

bool TraceAny(
    const Ray& ray,
    const BVH& bvh)
{
    std::array<uint32_t, 64> stack{};
    uint32_t stackSize = 0;

    stack[stackSize++] = 0;

    while (stackSize)
    {
        const BVHNode& node =
            bvh.nodes[
                stack[--stackSize]];

        if (!IntersectAABB(
                ray,
                node.bounds))
        {
            continue;
        }

        if (node.IsLeaf())
        {
            for (uint32_t i = 0;
                 i < node.primitiveCount;
                 ++i)
            {
                if (IntersectPrimitive(
                        ray,
                        node.Primitive(i)))
                {
                    // Nothing else matters.
                    return true;
                }
            }
        }
        else
        {
            stack[stackSize++] =
                node.left;

            stack[stackSize++] =
                node.right;
        }
    }

    return false;
}

Color TraceWhitted(
    const Scene& scene,
    const Ray& ray,
    uint32_t depth)
{
    if (depth >= scene.maxDepth)
        return Color::Black();

    const auto hit =
        scene.IntersectClosest(ray);

    if (!hit)
        return scene.Environment(ray.Direction);

    const Material& material =
        scene.Material(hit->MaterialID);

    if (material.IsEmissive())
        return material.Emission;

    // ---------------------------------------------------------
    // Perfect mirror.
    // ---------------------------------------------------------
    if (material.IsMirror())
    {
        const Vec3 reflection =
            Reflect(
                ray.Direction,
                hit->GeometricNormal);

        Ray child =
            SpawnRay(
                *hit,
                reflection);

        return
            material.Reflectance *
            TraceWhitted(
                scene,
                child,
                depth + 1);
    }

    // ---------------------------------------------------------
    // Ideal dielectric.
    // ---------------------------------------------------------
    if (material.IsGlass())
    {
        const bool entering =
            hit->FrontFace;

        const float etaI =
            entering ? 1.0f : material.IOR;

        const float etaT =
            entering ? material.IOR : 1.0f;

        const Vec3 N =
            hit->FaceForwardNormal();

        const Vec3 reflection =
            Reflect(
                ray.Direction,
                N);

        const float F =
            Fresnel(...);

        Color result =
            F *
            TraceWhitted(
                scene,
                SpawnRay(
                    *hit,
                    reflection),
                depth + 1);

        auto transmission =
            Refract(
                ray.Direction,
                N,
                etaI / etaT);

        if (transmission)
        {
            result +=
                (1.0f - F) *
                TraceWhitted(
                    scene,
                    SpawnTransmissionRay(
                        *hit,
                        *transmission),
                    depth + 1);
        }

        return result;
    }

    // ---------------------------------------------------------
    // Local/direct surface shading.
    // ---------------------------------------------------------
    Color Lo =
        material.Emission;

    for (const Light& light :
         scene.Lights())
    {
        LightSample sample =
            light.Sample(hit->Position);

        if (sample.NdotL <= 0.0f)
            continue;

        Ray shadow =
            SpawnShadowRay(
                *hit,
                sample.Direction,
                sample.Distance);

        if (scene.Occluded(shadow))
            continue;

        const Color fr =
            EvaluateBRDF(
                material,
                *hit,
                -ray.Direction,
                sample.Direction);

        Lo +=
            fr *
            sample.Radiance *
            sample.NdotL;
    }

    return Lo;
}

Color IntegrateSurface(
    SurfaceHit hit,
    Vec3 wo)
{
    Color result =
        hit.material.Emission;

    for all incoming directions wi:
    {
        Color Li =
            TraceRayFromSurface(
                hit,
                wi);

        Color fr =
            hit.material.BRDF(
                wi,
                wo);

        result +=
            fr *
            Li *
            max(
                Dot(hit.normal, wi),
