Color EstimateSurfaceRadiance(
    const SurfaceHit& hit,
    Vec3 wo,
    RNG& rng,
    uint32_t sampleCount)
{
    Color result =
        hit.Material.Emission;

    for (uint32_t s = 0;
         s < sampleCount;
         ++s)
    {
        DirectionSample sample =
            SampleIncomingDirection(
                hit,
                rng);

        const Vec3 wi =
            sample.Direction;

        const float pdf =
            sample.Pdf;

        if (pdf <= 0.0f)
            continue;

        const float cosine =
            std::max(
                Dot(
                    hit.ShadingNormal,
                    wi),
                0.0f);

        if (cosine <= 0.0f)
            continue;

        const Color fr =
            EvaluateBRDF(
                hit,
                wi,
                wo);

        Ray nextRay =
            SpawnRay(
                hit,
                wi);

        const Color Li =
            TracePath(nextRay, rng);

        result +=
            fr *
            Li *
            (cosine / pdf);
    }

    return
        result /
        static_cast<float>(
            sampleCount);
}

