DielectricSample SampleDielectric(
    const SurfaceHit& hit,
    const Ray& ray,
    MediumStack& media,
    const Material& material,
    RNG& rng)
{
    const Vec3 Ng =
        hit.GeometricNormal;

    const bool entering =
        hit.FrontFace;

    // Orient the interface normal against incident travel.
    const Vec3 N =
        entering ? Ng : -Ng;

    const MediumID currentMedium =
        media.Current();

    const MediumID targetMedium =
        entering
            ? material.InteriorMedium
            : media.BelowTop();

    const float etaI =
        GetMedium(currentMedium).IOR;

    const float etaT =
        GetMedium(targetMedium).IOR;

    const float eta =
        etaI / etaT;

    const float cosThetaI =
        std::clamp(
            Dot(-ray.Direction, N),
            0.0f,
            1.0f);

    const float sin2ThetaT =
        eta * eta *
        (1.0f -
         cosThetaI * cosThetaI);

    // Total internal reflection.
    if (sin2ThetaT > 1.0f)
    {
        return
        {
            .Wi =
                Reflect(
                    ray.Direction,
                    N),

            .Reflection = true,
            .EventProbability = 1.0f,
            .NextMedium = currentMedium
        };
    }

    const float F =
        FresnelDielectric(
            cosThetaI,
            etaI,
            etaT);

    if (rng.NextFloat() < F)
    {
        return
        {
            .Wi =
                Reflect(
                    ray.Direction,
                    N),

            .Reflection = true,
            .EventProbability = F,
            .NextMedium = currentMedium
        };
    }

    const Vec3 transmitted =
        Refract(
            ray.Direction,
            N,
            eta);

    return
    {
        .Wi = transmitted,
        .Transmission = true,
        .EventProbability = 1.0f - F,
        .NextMedium = targetMedium
    };
}

